class Solution {
    public int minSteps(int n){
        int answer=0;
        for(int divisor=2;divisor*divisor<=n;divisor++)while(n%divisor==0){
            answer+=divisor;
            n/=divisor;
        }
        if(n>1)answer+=n;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minSteps(n:Int):Int{
        var value=n;
        var answer=0;
        var divisor=2;
        while(divisor*divisor<=value){
            while(value%divisor==0){
                answer+=divisor;
                value/=divisor
            };
            divisor++
        };
        if(value>1)answer+=value;
        return answer
    }
}

